1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export interface QuoteResult {
36	  premium: number;
37	}
38	
39	export interface ClaimResult {
40	  payout: number;
41	  remainingCap: number;
42	}
43	
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export interface ScenarioResult {
47	  results: StepResult[];
48	}
49	
50	const PROCESSING_FEE = 5;
51	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
52	const CURSE_SURCHARGE_PERCENT = 50;
53	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
54	const ENCHANTMENT_SURCHARGE_PERCENT = 30;
55	const LOYALTY_YEARS = 2;
56	const LOYALTY_DISCOUNT_PERCENT = 20;
57	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
58	
59	/** What the MHPCO knows about a kind of item it will insure: what insuring
60	 *  one costs (`basePremium`), and what one is insured FOR (`insuranceValue`,
61	 *  from which the cap is derived — never from premiums). One entry per kind,
62	 *  so the two figures for a kind cannot drift apart. */
63	interface ItemKind {
64	  basePremium: number;
65	  insuranceValue: number;
66	}
67	
68	/** The MHPCO's price list. */
69	const ITEM_KINDS: Record<string, ItemKind> = {
70	  sword: { basePremium: 100, insuranceValue: 1000 },
71	  amulet: { basePremium: 60, insuranceValue: 600 },
72	  staff: { basePremium: 80, insuranceValue: 800 },
73	  potion: { basePremium: 40, insuranceValue: 400 },
74	  rune: { basePremium: 25, insuranceValue: 250 },
75	  moonstone: { basePremium: 25, insuranceValue: 250 },
76	};
77	
78	/** The price list entry for a type. The MHPCO insures only what its price
79	 *  list names, so an unlisted type is rejected rather than priced. */
80	const itemKindOf = (type: string): ItemKind => {
81	  const kind = ITEM_KINDS[type];
82	  if (kind === undefined) {
83	    throw new Error(`unknown item type: ${type}`);
84	  }
85	  return kind;
86	};
87	
88	/** What insuring this item costs, before any modifier. */
89	const basePremiumOf = (item: Item): number => itemKindOf(item.type).basePremium;
90	
91	/** What this item is insured FOR — the figure the cap derives from. Unmodified
92	 *  by anything that moves the premium: a curse costs more to insure without
93	 *  making the sword worth more. */
94	const insuranceValueOf = (item: Item): number =>
95	  itemKindOf(item.type).insuranceValue;
96	
97	const DEDUCTIBLE_PER_DAMAGED_ITEM = 100;
98	const CAP_MULTIPLE = 2;
99	
100	/** The enchantment level from which a CLAIM is only half reimbursed. A claim
101	 *  rule, unrelated to ENCHANTMENT_SURCHARGE_LEVEL, which gates a premium
102	 *  surcharge — the two thresholds differ and move independently. */
103	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
104	const HALF_REIMBURSEMENT_PERCENT = 50;
105	
106	/** Modifiers are expressed as an amount to add, never as a factor to multiply
107	 *  by, so that they stay additive against their base and so that the integer
108	 *  numerator keeps float artifacts out of the final rounding
109	 *  (100 * 1.1 === 110.000…1, but (100 * 10) / 100 === 10 exactly). */
110	const percentOf = (amount: number, percent: number): number =>
111	  (amount * percent) / 100;
112	
113	/** Rounds up — premiums round in the MHPCO's favour. */
114	const roundPremium = (amount: number): number => Math.ceil(amount);
115	
116	/** Rounds down — payouts, too, round in the MHPCO's favour. */
117	const roundPayout = (amount: number): number => Math.floor(amount);
118	
119	const COMPONENT_BLOCK_SIZE = 3;
120	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
121	
122	const COMPONENT_TYPES = ["rune", "moonstone"];
123	
124	const isComponent = (item: Item): boolean =>
125	  COMPONENT_TYPES.includes(item.type);
126	
127	const countByType = (items: Item[]): Map<string, number> => {
128	  const counts = new Map<string, number>();
129	  for (const item of items) {
130	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
131	  }
132	  return counts;
133	};
134	
135	/** A block is exactly three alike components, priced as a unit rather than
136	 *  per item. Larger counts do not decompose into blocks: 7 runes cost 7 × 25. */
137	const componentGroupBasePremium = ([type, count]: [string, number]): number =>
138	  count === COMPONENT_BLOCK_SIZE
139	    ? COMPONENT_BLOCK_BASE_PREMIUM
140	    : count * itemKindOf(type).basePremium;
141	
142	const sum = (amounts: number[]): number =>
143	  amounts.reduce((total, amount) => total + amount, 0);
144	
145	const policyBasePremium = (items: Item[]): number => {
146	  const mainItems = items.filter((item) => !isComponent(item));
147	  const componentGroups = [...countByType(items.filter(isComponent))];
148	
149	  return (
150	    sum(mainItems.map(basePremiumOf)) +
151	    sum(componentGroups.map(componentGroupBasePremium))
152	  );
153	};
154	
155	interface ItemModifierRule {
156	  appliesTo: (item: Item) => boolean;
157	  percent: number;
158	}
159	
160	/** Every item-scoped modifier, as a rule that either applies to an item or
161	 *  does not. Applicable rules stack. */
162	const ITEM_MODIFIER_RULES: ItemModifierRule[] = [
163	  {
164	    appliesTo: (item) => item.cursed === true,
165	    percent: CURSE_SURCHARGE_PERCENT,
166	  },
167	  {
168	    appliesTo: (item) => (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_LEVEL,
169	    percent: ENCHANTMENT_SURCHARGE_PERCENT,
170	  },
171	];
172	
173	/** Item-scoped modifiers apply to the affected item's own base premium,
174	 *  not to the policy total. */
175	const itemModifierAmount = (item: Item): number =>
176	  sum(
177	    ITEM_MODIFIER_RULES.filter((rule) => rule.appliesTo(item)).map((rule) =>
178	      percentOf(basePremiumOf(item), rule.percent),
179	    ),
180	  );
181	
182	/** A policy written by a quote step, as later claim steps see it. The insured
183	 *  items are kept because a damage entry names only a type, while the clauses
184	 *  that govern its reimbursement depend on the insured item itself. */
185	interface Policy {
186	  remainingCap: number;
187	  items: Item[];
188	}
189	
190	/** What a step leaves behind for the steps after it. Steps are not
191	 *  independent: a quote is priced against how many contracts precede it, and
192	 *  a claim is paid against a policy an earlier quote wrote, so running a
193	 *  scenario threads this state from each step to the next. */
194	interface ScenarioState {
195	  customer: Customer;
196	  precedingContracts: number;
197	  /** Keyed by the zero-based index of the quote step that wrote the policy —
198	   *  which is what a claim step's `policy` field refers to. */
199	  policiesByStep: Record<number, Policy>;
200	}
201	
202	const initialState = (customer: Customer): ScenarioState => ({
203	  customer,
204	  precedingContracts: 0,
205	  policiesByStep: {},
206	});
207	
208	/** A step's outcome: what it reports, and the state the next step sees. */
209	interface StepOutcome {
210	  result: StepResult;
211	  state: ScenarioState;
212	}
213	
214	/** What a policy-wide rule may look at: the customer, plus where this quote
215	 *  sits in the customer's history of contracts. A pricing view of the
216	 *  scenario state — rules read it, they never advance it. */
217	type PolicyContext = Readonly<ScenarioState>;
218	
219	interface PolicyModifierRule {
220	  appliesTo: (context: PolicyContext) => boolean;
221	  /** Signed: positive surcharges, negative discounts. */
222	  percent: number;
223	}
224	
225	/** Every policy-wide modifier, as a rule that either applies to a policy or
226	 *  does not. Applicable rules stack. */
227	const POLICY_MODIFIER_RULES: PolicyModifierRule[] = [
228	  {
229	    appliesTo: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
230	    percent: -LOYALTY_DISCOUNT_PERCENT,
231	  },
232	  {
233	    appliesTo: () => true,
234	    percent: FIRST_INSURANCE_SURCHARGE_PERCENT,
235	  },
236	  {
237	    appliesTo: ({ precedingContracts }) => precedingContracts > 0,
238	    percent: -FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
239	  },
240	];
241	
242	/** Policy-wide modifiers apply to the policy base premium — the sum of every
243	 *  item's base premium — not to any single item. */
244	const policyModifierAmount = (
245	  basePremium: number,
246	  context: PolicyContext,
247	): number =>
248	  sum(
249	    POLICY_MODIFIER_RULES.filter((rule) => rule.appliesTo(context)).map(
250	      (rule) => percentOf(basePremium, rule.percent),
251	    ),
252	  );
253	
254	const quote = (items: Item[], context: PolicyContext): QuoteResult => {
255	  const basePremium = policyBasePremium(items);
256	  // Every modifier is an amount added to the base premium, not a factor
257	  // compounded onto a running total: item-scoped modifiers take a percentage
258	  // of their own item's base premium, policy-wide ones take a percentage of
259	  // the policy base premium.
260	  const modifierAmounts = [
261	    ...items.map(itemModifierAmount),
262	    policyModifierAmount(basePremium, context),
263	  ];
264	  // The processing fee is added last, after all percentage modifiers.
265	  const premium = basePremium + sum(modifierAmounts) + PROCESSING_FEE;
266	  return { premium: roundPremium(premium) };
267	};
268	
269	/** The cap on everything a policy will ever pay out: twice the sum of the
270	 *  insured items' values. Premium modifiers do not raise it. */
271	const policyCap = (items: Item[]): number =>
272	  CAP_MULTIPLE * sum(items.map(insuranceValueOf));
273	
274	/** What one damage entry reimburses before the deductible: the full damage,
275	 *  unless a special clause reduces it. */
276	const reimbursableAmount = (damage: Damage, insuredItem: Item): number =>
277	  (insuredItem.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
278	    ? percentOf(damage.amount, HALF_REIMBURSEMENT_PERCENT)
279	    : damage.amount;
280	
281	/** The insured item a damage entry refers to. A damage entry names only a
282	 *  type, while the clauses governing its reimbursement depend on the item.
283	 *  The MHPCO pays only for what it insured, so a damage entry naming a type
284	 *  the policy does not cover is rejected rather than reimbursed. */
285	const insuredItemFor = (damage: Damage, policy: Policy): Item => {
286	  const insuredItem = policy.items.find(
287	    (item) => item.type === damage.itemType,
288	  );
289	  if (insuredItem === undefined) {
290	    throw new Error(`damaged item is not insured: ${damage.itemType}`);
291	  }
292	  return insuredItem;
293	};
294	
295	/** A damage entry states what an incident cost. An amount below zero states
296	 *  that the incident paid the claimant, which is not a thing an incident can
297	 *  do — so it is rejected as malformed rather than reimbursed. Zero is a
298	 *  well-formed claim for nothing, and passes. */
299	const validDamage = (damage: Damage): Damage => {
300	  if (damage.amount < 0) {
301	    throw new Error(`damage amount must not be negative: ${damage.amount}`);
302	  }
303	  return damage;
304	};
305	
306	/** What one damage entry claims: the reimbursable amount, less the deductible
307	 *  that is charged once per damaged item. Not yet what the policy pays — the
308	 *  cap applies to the incident total, not to any single entry, and rounding
309	 *  comes later still, so this figure stays fractional. */
310	const claimedForDamage = (damage: Damage, policy: Policy): number =>
311	  reimbursableAmount(validDamage(damage), insuredItemFor(damage, policy)) -
312	  DEDUCTIBLE_PER_DAMAGED_ITEM;
313	
314	/** The state that results from recording one policy against a step index,
315	 *  replacing any policy already recorded there. */
316	const withPolicy = (
317	  state: ScenarioState,
318	  stepIndex: number,
319	  policy: Policy,
320	): ScenarioState => ({
321	  ...state,
322	  policiesByStep: { ...state.policiesByStep, [stepIndex]: policy },
323	});
324	
325	/** Writes a policy, and records it so later claim steps can be paid against
326	 *  it. Each quote written also becomes a preceding contract for the next. */
327	const runQuote = (
328	  step: QuoteStep,
329	  stepIndex: number,
330	  state: ScenarioState,
331	): StepOutcome => ({
332	  result: quote(step.items, state),
333	  state: withPolicy(
334	    { ...state, precedingContracts: state.precedingContracts + 1 },
335	    stepIndex,
336	    { remainingCap: policyCap(step.items), items: step.items },
337	  ),
338	});
339	
340	/** The MHPCO insures items, not types: a policy covering one sword answers
341	 *  for one damaged sword. More entries of a type than the policy covers
342	 *  rejects the whole claim, not merely the surplus entry. */
343	const rejectOverclaimedTypes = (damages: Damage[], policy: Policy): void => {
344	  const insuredCounts = countByType(policy.items);
345	  const damageCounts = new Map<string, number>();
346	  for (const damage of damages) {
347	    const claimed = (damageCounts.get(damage.itemType) ?? 0) + 1;
348	    damageCounts.set(damage.itemType, claimed);
349	    if (claimed > (insuredCounts.get(damage.itemType) ?? 0)) {
350	      throw new Error(
351	        `more damage entries than insured items of type: ${damage.itemType}`,
352	      );
353	    }
354	  }
355	};
356	
357	/** What an incident claims in total, before the policy's cap is applied:
358	 *  every damage entry reimbursed on its own terms, less its own deductible. */
359	const claimedAmount = (damages: Damage[], policy: Policy): number => {
360	  rejectOverclaimedTypes(damages, policy);
361	  return sum(damages.map((damage) => claimedForDamage(damage, policy)));
362	};
363	
364	/** A policy never pays out more than the cap it has left, so a claim that
365	 *  exhausts the cap is paid down to it rather than past it. */
366	const paidWithinCap = (claimed: number, remainingCap: number): number =>
367	  Math.min(claimed, remainingCap);
368	
369	/** What a policy actually hands over for one incident: what the incident
370	 *  claims, held to what the cap has left, and only then rounded. Rounding
371	 *  last is what keeps the intermediates fractional — a half-reimbursed
372	 *  damage stays at 450.5 until the whole payout is settled. */
373	const payoutFor = (damages: Damage[], policy: Policy): number =>
374	  roundPayout(
375	    paidWithinCap(claimedAmount(damages, policy), policy.remainingCap),
376	  );
377	
378	/** Pays a claim against the policy an earlier quote step wrote, drawing the
379	 *  payout down from that policy's remaining cap. */
380	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
381	  const policy = state.policiesByStep[step.policy];
382	  const payout = payoutFor(step.incident.damages, policy);
383	  const remainingCap = policy.remainingCap - payout;
384	  return {
385	    result: { payout, remainingCap },
386	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
387	  };
388	};
389	
390	const runStep = (
391	  step: Step,
392	  stepIndex: number,
393	  state: ScenarioState,
394	): StepOutcome =>
395	  step.op === "quote"
396	    ? runQuote(step, stepIndex, state)
397	    : runClaim(step, state);
398	
399	export const runScenario = (scenario: Scenario): ScenarioResult => {
400	  const { results } = scenario.steps.reduce(
401	    ({ results, state }, step, stepIndex) => {
402	      const outcome = runStep(step, stepIndex, state);
403	      return { results: [...results, outcome.result], state: outcome.state };
404	    },
405	    { results: [] as StepResult[], state: initialState(scenario.customer) },
406	  );
407	  return { results };
408	};
